begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,is_anonymous,raw_user_meta_data)
 select ('51000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'synthetic-delegation-'||n||'@example.test',case when n=5 then null else now() end,false,'{"role":"owner","clinical_signer":true}' from generate_series(1,6)n;
insert into auth.sessions(id,user_id,not_after) select ('52000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('51000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,now()+interval '1 hour' from generate_series(1,6)n;
insert into public.doctor_profiles(user_id,display_name)values('51000000-0000-0000-0000-000000000001','Synthetic doctor A'),('51000000-0000-0000-0000-000000000002','Synthetic doctor B');
insert into public.practices(id,owner_user_id,name)values('53000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','Synthetic A'),('53000000-0000-0000-0000-000000000002','51000000-0000-0000-0000-000000000002','Synthetic B');
insert into public.locations(id,practice_id,name,timezone)values
 ('54000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000001','A first','Africa/Cairo'),
 ('54000000-0000-0000-0000-000000000002','53000000-0000-0000-0000-000000000001','A second','Europe/London'),
 ('54000000-0000-0000-0000-000000000003','53000000-0000-0000-0000-000000000002','B first','Etc/UTC');
create temp table invitation_test(label text primary key,result jsonb);
grant select,insert on invitation_test to authenticated;
create function pg_temp.claim(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub','51000000-0000-0000-0000-'||lpad(n::text,12,'0'),'session_id','52000000-0000-0000-0000-'||lpad(n::text,12,'0'),'role','authenticated','user_metadata',jsonb_build_object('role','owner','clinical_signer',true))::text,true)$$;
set local role authenticated;
select pg_temp.claim(1);
insert into invitation_test values('A',public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','  Synthetic-delegation-3@Example.test  ',encode(sha256(decode(repeat('a',64),'hex')),'hex'),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["locations.read","patients.read"]},{"location_id":"54000000-0000-0000-0000-000000000002","capabilities":["appointments.read"]}]','56000000-0000-0000-0000-000000000001'));
select is(public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','  Synthetic-delegation-3@Example.test  ',encode(sha256(decode(repeat('a',64),'hex')),'hex'),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["locations.read","patients.read"]},{"location_id":"54000000-0000-0000-0000-000000000002","capabilities":["appointments.read"]}]','56000000-0000-0000-0000-000000000001'),(select result from invitation_test where label='A'),'DOS-M1-009-C01: invitation creation retry returns the original receipt');
select is((public.doctor_team('53000000-0000-0000-0000-000000000001')->>'invitation_total')::integer,1,'creation retry makes one invitation');
select is(public.doctor_team('53000000-0000-0000-0000-000000000001')->'invitations'->0->>'recipient_email','synthetic-delegation-3@example.test','recipient address is normalized for explicit verified-recipient binding');
select ok(not(public.doctor_team('53000000-0000-0000-0000-000000000001')->'invitations'->0 ? 'token_hash'),'owner directory never exposes the credential hash');
select throws_ok($$select * from public.secretary_invitations$$,'42501',null,'even the owner cannot read the credential table directly');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-3@example.test',repeat('a',64),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["locations.read"]}]','56000000-0000-0000-0000-000000000002')$$,'23505','DOCTOR_INVITATION_EXISTS','new command cannot duplicate a pending recipient invitation');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000002','synthetic-delegation-4@example.test',repeat('a',64),'[]','56000000-0000-0000-0000-000000000003')$$,'42501','DOCTOR_ACCESS_DENIED','cross-doctor invitation is denied');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-4@example.test',repeat('a',64),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["clinical.sign"]}]','56000000-0000-0000-0000-000000000004')$$,'22023','DOCTOR_GRANTS_INVALID','invitation cannot grant clinical signing');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-4@example.test',repeat('a',64),'[{"location_id":"54000000-0000-0000-0000-000000000003","capabilities":["locations.read"]}]','56000000-0000-0000-0000-000000000005')$$,'22023','DOCTOR_GRANTS_INVALID','invitation cannot contain another doctor location');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-4@example.test',repeat('a',64),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["patients.read"],"role":"owner"}]','56000000-0000-0000-0000-000000000006')$$,'22023','DOCTOR_GRANTS_INVALID','overposted authority fields are rejected');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-4@example.test',repeat('a',64),'[]','56000000-0000-0000-0000-000000000007')$$,'22023','DOCTOR_GRANTS_INVALID','an invitation needs an explicit positive administrative scope');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','bad address',repeat('a',64),'[]','56000000-0000-0000-0000-000000000008')$$,'22023','DOCTOR_INVITATION_INVALID','malformed recipient input is rejected');
select throws_ok($$select public.doctor_team('53000000-0000-0000-0000-000000000001',0,101)$$,'22023','DOCTOR_QUERY_INVALID','team query is bounded');
insert into invitation_test values('expired',public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-6@example.test',encode(sha256(decode(repeat('c',64),'hex')),'hex'),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["patients.read"]}]','56000000-0000-0000-0000-000000000009'));
insert into invitation_test values('cancelled',public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-4@example.test',encode(sha256(decode(repeat('d',64),'hex')),'hex'),'[{"location_id":"54000000-0000-0000-0000-000000000001","capabilities":["patients.read"]}]','56000000-0000-0000-0000-000000000010'));
select lives_ok($$select public.doctor_cancel_secretary_invitation('53000000-0000-0000-0000-000000000001',(select (result->>'invitation_id')::uuid from invitation_test where label='cancelled'),1,'56000000-0000-0000-0000-000000000011')$$,'owner cancels only its own pending invitation');
select pg_temp.claim(2);
insert into invitation_test values('B',public.doctor_invite_secretary('53000000-0000-0000-0000-000000000002','synthetic-delegation-3@example.test',encode(sha256(decode(repeat('b',64),'hex')),'hex'),'[{"location_id":"54000000-0000-0000-0000-000000000003","capabilities":["locations.read","locations.manage","appointments.read"]}]','56000000-0000-0000-0000-000000000012'));
select throws_ok($$select public.doctor_cancel_secretary_invitation('53000000-0000-0000-0000-000000000002',(select (result->>'invitation_id')::uuid from invitation_test where label='A'),1,'56000000-0000-0000-0000-000000000013')$$,'42501','DOCTOR_ACCESS_DENIED','another doctor cannot cancel practice A invitation');
select pg_temp.claim(4);
select throws_ok($$select public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64))$$,'42501','DOCTOR_INVITATION_UNAVAILABLE','right credential with wrong confirmed recipient is denied');
select throws_ok($$select public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='cancelled'),repeat('d',64))$$,'42501','DOCTOR_INVITATION_UNAVAILABLE','cancelled credential cannot be used');
select pg_temp.claim(5);
select throws_ok($$select public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64))$$,'42501','DOCTOR_AUTH_REQUIRED','unconfirmed identity cannot review or accept an invitation');
reset role;
update public.secretary_invitations set expires_at=clock_timestamp()-interval '1 second' where id=(select (result->>'invitation_id')::uuid from invitation_test where label='expired');
set local role authenticated;
select pg_temp.claim(6);
select throws_ok($$select public.doctor_accept_secretary_invitation((select (result->>'invitation_id')::uuid from invitation_test where label='expired'),repeat('c',64),'56000000-0000-0000-0000-000000000014')$$,'42501','DOCTOR_INVITATION_UNAVAILABLE','expired pending invitation cannot be accepted');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('0',64))$$,'42501','DOCTOR_INVITATION_UNAVAILABLE','verified email alone without the secret never grants access');
select is(public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64))->>'doctor_name','Synthetic doctor A','recipient reviews the exact stored owning doctor before acceptance');
select is(jsonb_array_length(public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64))->'grants'),2,'review lists the two explicit location grants');
select ok(not(public.doctor_invitation_details((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64)) ? 'token_hash'),'review response has no credential hash');
insert into invitation_test values('accepted-A',public.doctor_accept_secretary_invitation((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64),'56000000-0000-0000-0000-000000000015'));
select is(public.doctor_accept_secretary_invitation((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64),'56000000-0000-0000-0000-000000000015'),(select result from invitation_test where label='accepted-A'),'DOS-M1-009-C01: exact acceptance retry returns the original membership');
select throws_ok($$select public.doctor_accept_secretary_invitation((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64),'56000000-0000-0000-0000-000000000016')$$,'42501','DOCTOR_INVITATION_UNAVAILABLE','accepted token cannot create a new acceptance intent');
select is((select count(*) from public.memberships),1::bigint,'secretary receives one membership after duplicate acceptance');
select is((select count(*) from public.doctor_profiles where user_id='51000000-0000-0000-0000-000000000003'),0::bigint,'DOS-M1-009-C04: secretary acceptance creates no doctor owner profile');
select is((select count(*) from public.practices where owner_user_id='51000000-0000-0000-0000-000000000003'),0::bigint,'secretary never becomes a practice owner or subscriber');
insert into invitation_test values('accepted-B',public.doctor_accept_secretary_invitation((select (result->>'invitation_id')::uuid from invitation_test where label='B'),repeat('b',64),'56000000-0000-0000-0000-000000000017'));
select is((select count(*) from public.memberships),2::bigint,'DOS-M1-009-C02: one secretary holds two independent doctor memberships');
select is((select version from public.memberships where id=(select (result->>'membership_id')::uuid from invitation_test where label='accepted-A')),1,'second invitation leaves the first membership version unchanged');
select is(jsonb_array_length(public.doctor_contexts()),3,'both doctor memberships resolve their explicitly granted locations');
select is(public.doctor_resolve_context('53000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000001')->>'portal','secretary','editable owner/clinical metadata cannot promote the portal');
select is((public.doctor_locations('53000000-0000-0000-0000-000000000001')->>'total')::integer,1,'location settings list does not mix another location administrative scope');
select is((public.doctor_locations('53000000-0000-0000-0000-000000000002')->>'total')::integer,1,'second practice settings list remains independently scoped');
select throws_ok($$select public.doctor_write_location('53000000-0000-0000-0000-000000000001','Denied','Etc/UTC','','','56000000-0000-0000-0000-000000000018','54000000-0000-0000-0000-000000000001',1)$$,'42501','DOCTOR_ACCESS_DENIED','practice A read permission cannot use B management authority');
select throws_ok($$select public.doctor_team('53000000-0000-0000-0000-000000000001')$$,'42501','DOCTOR_ACCESS_DENIED','secretary cannot view owner team contact/directory data');
select throws_ok($$select public.doctor_invite_secretary('53000000-0000-0000-0000-000000000001','synthetic-delegation-4@example.test',repeat('a',64),'[]','56000000-0000-0000-0000-000000000019')$$,'42501','DOCTOR_ACCESS_DENIED','secretary cannot invite or delegate itself owner authority');
select throws_ok($$update public.memberships set capabilities=array['locations.manage']$$,'42501',null,'direct membership changes are denied');
select pg_temp.claim(1);
select lives_ok($$select public.doctor_set_membership_status('53000000-0000-0000-0000-000000000001',(select (result->>'membership_id')::uuid from invitation_test where label='accepted-A'),1,'revoked','56000000-0000-0000-0000-000000000020')$$,'owner revokes its own membership with an explicit versioned command');
select pg_temp.claim(3);
select is(jsonb_array_length(public.doctor_contexts()),1,'DOS-M1-009-C03: same open session loses only revoked doctor contexts');
select throws_ok($$select public.doctor_locations('53000000-0000-0000-0000-000000000001')$$,'42501','DOCTOR_ACCESS_DENIED','next protected request is denied without JWT refresh');
select throws_ok($$select public.doctor_accept_secretary_invitation((select (result->>'invitation_id')::uuid from invitation_test where label='A'),repeat('a',64),'56000000-0000-0000-0000-000000000015')$$,'42501','DOCTOR_INVITATION_UNAVAILABLE','an old successful acceptance receipt cannot reactivate revoked access');
select is((select status from public.memberships where id=(select (result->>'membership_id')::uuid from invitation_test where label='accepted-B')),'active','revocation leaves the other doctor membership unchanged');
select pg_temp.claim(2);
select lives_ok($$select public.doctor_set_membership_status('53000000-0000-0000-0000-000000000002',(select (result->>'membership_id')::uuid from invitation_test where label='accepted-B'),1,'suspended','56000000-0000-0000-0000-000000000021')$$,'second doctor can suspend only its own secretary membership');
select pg_temp.claim(3);
select is(jsonb_array_length(public.doctor_contexts()),0,'suspension removes the remaining operational context');
select throws_ok($$select public.doctor_resolve_context('53000000-0000-0000-0000-000000000002','54000000-0000-0000-0000-000000000003')$$,'42501','DOCTOR_CONTEXT_DENIED','suspended open session cannot resolve a cached context');
select pg_temp.claim(2);
select lives_ok($$select public.doctor_set_membership_status('53000000-0000-0000-0000-000000000002',(select (result->>'membership_id')::uuid from invitation_test where label='accepted-B'),2,'active','56000000-0000-0000-0000-000000000022')$$,'only the owning doctor can explicitly restore suspended access');
select pg_temp.claim(3);
select is(jsonb_array_length(public.doctor_contexts()),1,'restoring B never restores revoked A');
reset role;
select is((select count(*) from public.audit_events where event_type='secretary.accepted'),2::bigint,'each independent acceptance has one immutable attributed audit event');
select is((select count(*) from public.practices),2::bigint,'DOS-M1-009-C04: both doctor ownership associations survive unchanged');
select is((select count(*) from doctor_private.command_receipts where request::text like '%'||repeat('a',64)||'%' or result::text like '%'||repeat('a',64)||'%'),0::bigint,'raw invitation secret never enters persisted command receipts');
set local role anon;
select throws_ok($$select public.doctor_team('53000000-0000-0000-0000-000000000001')$$,'42501',null,'anonymous team read is denied');
select throws_ok($$select public.doctor_invitation_details('55000000-0000-0000-0000-000000000001',repeat('a',64))$$,'42501',null,'anonymous invitation preview is denied');
reset role;
select * from finish();
rollback;
